Variable HI : heap_iface.

(* [comment removed for export] *)
Definition mulu_run_stmt : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (o sp r fb : Z) (len : nat) (v0 : Z),
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 NANOS ->
    getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp ->
    sp mod 16 = 0 -> 0x7fff7f800000 + ARITH_SCR <= sp -> L5.writable RSEGS M (sp - ARITH_SCR) ARITH_SCR -> L5.img_clear M 65536 814272 ->
    binl_at M o fb len v0 0 -> (len <= 1)%nat -> (len = 0%nat -> v0 = 0) ->
    o mod 8 = 0 -> sp <= o -> o + 32 < 2 ^ 47 -> L5.writable RSEGS M o 32 ->
    exists fx' R' M' (lo hi : Z), msteps RSEGS (st fx R MULU M) (st fx' R' r M')
      /\ mem_grows M M'
      /\ (forall a, 0 <= a < 2 ^ 64 -> ~ (sp - ARITH_SCR <= a < sp) -> ~ (o <= a < o + 32) -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a))
      /\ (forall i, In i L5K.CS -> getr R' (reg i) = getr R (reg i)) /\ getr R' (reg 10) = Z_to_bv 64 o
      /\ lo + 2 ^ 64 * hi = v0 * NANOS /\ binl_at M' o (wfb fb lo hi) (wlen lo hi) lo hi.

(* [comment removed for export] *)
Definition add64_run_stmt : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (o y sp r fb : Z) (len : nat) (v0 : Z),
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 y -> 0 <= y -> v0 + y < 2 ^ 64 ->
    getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp ->
    sp mod 16 = 0 -> 0x7fff7f800000 + ARITH_SCR <= sp -> L5.writable RSEGS M (sp - ARITH_SCR) ARITH_SCR -> L5.img_clear M 65536 814272 ->
    binl_at M o fb len v0 0 -> (len <= 1)%nat -> (len = 0%nat -> v0 = 0) -> Z.testbit fb 1 = false ->
    o mod 8 = 0 -> sp <= o -> o + 32 < 2 ^ 47 -> L5.writable RSEGS M o 32 ->
    exists fx' R' M', msteps RSEGS (st fx R ADDU64 M) (st fx' R' r M')
      /\ mem_grows M M'
      /\ (forall a, 0 <= a < 2 ^ 64 -> ~ (sp - ARITH_SCR <= a < sp) -> ~ (o <= a < o + 32) -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a))
      /\ (forall i, In i L5K.CS -> getr R' (reg i) = getr R (reg i)) /\ getr R' (reg 10) = Z_to_bv 64 o
      /\ binl_at M' o fb (wlen (v0 + y) 0) (v0 + y) 0.

(* [comment removed for export] *)
Definition ws1_post (LB : list (Z * Z)) (M' : word -> option byte) (len : nat) (x x' : PM.vstr) (cr cr' : credit) : Prop :=
  match x, x' with
  | PM.VShort _, PM.VShort _ => len = 0%nat /\ cr' = cr
  | PM.VShort _, PM.VLong c' _ p' => (1 <= len)%nat /\ c' = 26 /\ cr' = debit L cr 26 /\ L5C.fresh_block L LB M' p' 26
  | PM.VLong c _ p, PM.VLong c' _ p' => c' = c /\ p' = p /\ cr' = cr
  | PM.VLong _ _ _, PM.VShort _ => False
  end.
(* [comment removed for export] *)
Definition ts_text (M : word -> option byte) (ot : Z) (x : PM.vstr) : Prop :=
  exists bs, L5.bytes_at RSEGS M (PM.vs_data ot x) bs /\ Z.of_nat (length bs) = PM.vs_size x /\ Forall (fun b => b = 45 \/ 48 <= b <= 57) bs.
Definition ws1_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (cr : credit) (o ot sp r fb : Z) (len : nat) (v0 : Z) (x : PM.vstr),
    hi_heap HI (PM.vs_own x ++ LB) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] ->
    getr R 10%bv = Z_to_bv 64 o -> getr R 11%bv = Z_to_bv 64 ot ->
    getr R 1%bv = Z_to_bv 64 r -> L5.ra_ok r -> getr R 2%bv = Z_to_bv 64 sp -> getr R 4%bv = Z_to_bv 64 (pa_tp AD) ->
    L5C.stk (hl_sptop L) M sp WRS_SCR -> PMST.base_ok RSEGS AD M ->
    binl_at M o fb len v0 0 -> len = wlen v0 0 ->
    o mod 8 = 0 -> sp <= o -> o + 32 <= hl_sptop L ->
    PM.vstr_at RSEGS PMSP.T3 M ot x -> PM.vs_size x = 0 -> ot mod 8 = 0 -> sp <= ot -> ot + 24 <= hl_sptop L -> (o + 32 <= ot \/ ot + 24 <= o) ->
    (match x with PM.VShort _ => (1 <= len)%nat -> credit_ok L cr 26 | _ => True end) ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : PM.vstr) (cr' : credit),
        regs_preserved R R' ->
        PM.vstr_at RSEGS PMSP.T3 M' ot x' -> 1 <= PM.vs_size x' <= 21 -> ts_text M' ot x' -> ws1_post LB M' len x x' cr cr' ->
        L5C.hpres L LB sp WRS_SCR [(ot, 24)] M M' ->
        model_but_vm model model' -> hi_heap HI (PM.vs_own x' ++ LB) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
    srealizes RSEGS SCFG (PMSP.cfg RSEGS R WRS M model) K.
End WithHeap.
End PQTSS.

