Definition NANOS : Z := 1000000000.
(* [comment removed for export] *)
Definition TOB_SCR : Z := 9216.
Definition DIV_SCR : Z := 480.
Definition TSNZ_SCR : Z := 64.

Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
