(* [comment removed for export] *)
Definition pol_ts_ok (P : NESK.sink_policy) : Prop :=
  forall c, NESK.is_cap c -> (0 < c -> NESK.sp_cap P c /\ c <= NESK.sp_nmax P) -> credit_okR (NESK.sink_pot P c) 64.

(* [comment removed for export] *)
Definition to_bigint_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (cr : credit) (s n o sp r : Z),
    hi_heap HI LB cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] ->
    getr R (reg 10) = Z_to_bv 64 s -> getr R (reg 11) = Z_to_bv 64 n -> getr R (reg 12) = Z_to_bv 64 o ->
    getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp -> getr R (reg 4) = Z_to_bv 64 (pa_tp AD) ->
    L5C.stk (hl_sptop L) M sp TOB_SCR -> PMST.base_ok RSEGS AD M ->
    (* [comment removed for export] *)
    0 <= n <= 31 -> 0 <= s -> s + n <= 2 ^ 47 -> L5.defined M s n ->
    (n = 0 \/ PGS.in_blk LB s n \/ (o + 32 <= s /\ s + n <= hl_sptop L)) ->
    (* [comment removed for export] *)
    PQTSS.binl_at M o 0 0 0 0 -> o mod 8 = 0 -> sp <= o -> o + 32 <= hl_sptop L -> L5.defined M o 32 ->
    credit_okR cr 64 ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (fb ec v0 v1 : Z) (len : nat),
        regs_preserved R R' -> getr R' (reg 11) = Z_to_bv 64 ec -> (ec = 0 \/ ec = 22) ->   (* [comment removed for export] *)
        PQTSS.binl_at M' o fb len v0 v1 -> (len <= 2)%nat -> len = PQTSS.wlen v0 v1 -> (fb = 0 \/ fb = 2) ->
        L5C.hpres L LB sp TOB_SCR [(o, 32)] M M' ->
        model_but_vm model model' -> hi_heap HI LB cr M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
    srealizes RSEGS SCFG (PMSP.cfg RSEGS R (ne_to_bigint E) M model) K.

(* [comment removed for export] *)
Definition tsnz_run_stmt : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (o sp r fb : Z) (len : nat) (v0 v1 : Z),
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 0 ->
    getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp ->
    sp mod 16 = 0 -> 0x7fff7f800000 + TSNZ_SCR <= sp -> L5.writable RSEGS M (sp - TSNZ_SCR) TSNZ_SCR ->
    PQTSS.binl_at M o fb len v0 v1 -> (len <= 2)%nat -> (fb = 0 \/ fb = 2) ->
    o mod 8 = 0 -> sp <= o -> o + 32 < 2 ^ 47 ->
    exists fx' R' M' (t : Z), msteps RSEGS (st fx R (ne_ts_helper E) M) (st fx' R' r M')
      /\ mem_grows M M'
      /\ (forall a, 0 <= a < 2 ^ 64 -> ~ (sp - TSNZ_SCR <= a < sp) -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a))
      /\ (forall i, In i L5K.CS -> getr R' (reg i) = getr R (reg i)) /\ getr R' (reg 2) = Z_to_bv 64 sp
      /\ getr R' (reg 10) = Z_to_bv 64 t /\ 0 <= t <= 1.

(* [comment removed for export] *)
Definition divnano_run_stmt : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (sp r fb : Z) (len : nat) (v0 v1 : Z),
    getr R (reg 10) = Z_to_bv 64 (sp + 104) -> getr R (reg 11) = Z_to_bv 64 (sp + 8) -> getr R (reg 12) = Z_to_bv 64 (sp + 72) ->
    getr R (reg 13) = Z_to_bv 64 (sp + 40) -> getr R (reg 14) = Z_to_bv 64 1 ->
    getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp ->
    sp mod 16 = 0 -> 0x7fff7f800000 + DIV_SCR <= sp -> sp + 136 < 2 ^ 47 ->
    L5.writable RSEGS M (sp - DIV_SCR) DIV_SCR -> L5.defined M (sp - DIV_SCR) DIV_SCR -> L5.writable RSEGS M sp 136 -> L5.defined M sp 136 ->
    PQTSS.binl_at M (sp + 104) fb len v0 v1 -> (len <= 2)%nat -> len = PQTSS.wlen v0 v1 -> (fb = 0 \/ fb = 2) ->
    PQTSS.binl_at M (sp + 8) 0 1 NANOS 0 ->
    PQTSS.binl_at M (sp + 72) 0 0 0 0 -> PQTSS.binl_at M (sp + 40) 0 0 0 0 ->
    exists fx' R' M' (fq : Z) (lq : nat) (fr : Z) (lr : nat),
      msteps RSEGS (st fx R (ne_divide E) M) (st fx' R' r M')
      /\ mem_grows M M'
      /\ (forall a, 0 <= a < 2 ^ 64 -> ~ (sp - DIV_SCR <= a < sp) -> ~ (sp + 8 <= a < sp + 136) -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a))
      /\ (forall i, In i L5K.CS -> getr R' (reg i) = getr R (reg i)) /\ getr R' (reg 2) = Z_to_bv 64 sp
      /\ L5.u8_at RSEGS M' (sp + 104) fb /\ L5.u8_at RSEGS M' (sp + 8) 0
      /\ L5.u8_at RSEGS M' (sp + 72) fq /\ 0 <= fq < 256 /\ Z.land fq 1 = 0 /\ L5.u64_at RSEGS M' (sp + 80) (Z.of_nat lq) /\ (lq <= 2)%nat
      /\ L5.u8_at RSEGS M' (sp + 40) fr /\ 0 <= fr < 256 /\ Z.land fr 1 = 0 /\ L5.u64_at RSEGS M' (sp + 48) (Z.of_nat lr) /\ (lr <= 1)%nat.
    (* [comment removed for export] *)

End WithHeap.

(* [comment removed for export] *)
Lemma pol_ts_ok_PME : pol_ts_ok NESK.PME.
Proof.
  intros c CAP H. unfold credit_okR, NESK.sink_pot, NESK.PME, NESK.SP_T, NESK.ZMAX, NESK.SMZ. cbn [NESK.sp_B NESK.sp_csz NESK.sp_cap NESK.sp_nmax fst snd] in *.
  assert (C64 : cszR 64 = 2 ^ 20) by (vm_compute; reflexivity).
  assert (C28 : 2 ^ 20 <= cszR (2 ^ 29 / 2)) by (vm_compute; discriminate).
  pose proof (NESK.cszR_nonneg (2 ^ 29)) as N29.
  destruct (Z.eqb_spec c 0) as [->|NZ].
  - split; [lia|]. rewrite C64. lia.
  - assert (HC : 0 < c) by (destruct CAP as [->|(e & He & ->)]; [congruence| apply Z.pow_pos_nonneg; lia]).
    destruct (H HC) as [_ Hle]. pose proof (NESK.cszR_mono c (2 ^ 29) Hle) as MC.
    split; [lia|]. rewrite C64. lia.
Qed.
End NETS.

