Section Specs.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable segs : list Segment.
Variable A : pm_addrs.
Variable L : heap_layout.
Variable HI : heap_iface.
Abbreviation kstr_at := (PQM.kstr_at segs PMSP.T3).
Abbreviation kcontent := (NEM.kcontent segs).

(* [comment removed for export] *)
Definition wd_specC (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (cr : credit) (o so os sp r g : Z) (x : PM.vstr) (bs : list Z),
    hi_heap HI (PM.vs_own x ++ LBX) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] ->
    WD.entry_scr A L R M sp r WD.WD_SCR ->
    getr R 10%bv = Z_to_bv 64 o -> getr R 11%bv = Z_to_bv 64 so ->
    WD.wd_at segs M o -> L5.u64_at segs M so os -> kstr_at M os x -> kcontent M os x bs -> PQM.ks_ok PQM.SMK x g -> os mod 8 = 0 ->
    PM.vs_size x + WD.WD_MAX <= PQM.SMK ->
    sp <= o -> o + 12 <= hl_sptop L -> sp <= so -> so + 8 <= hl_sptop L -> sp <= os -> os + 24 <= hl_sptop L ->
    WD.apart24 o 12 os -> WD.apart24 so 8 os ->
    PMST.base_ok segs A M -> PMSP.credit_le (PQM.pot_ks L PQM.SMK x g) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : PM.vstr) (g' : Z) (cr' : credit) (ds : list Z),
        regs_preserved R R' -> kstr_at M' os x' -> kcontent M' os x' (bs ++ ds) -> NEM.ascii ds -> PQM.ks_ok PQM.SMK x' g' ->
        PM.vs_size x <= PM.vs_size x' <= PM.vs_size x + WD.WD_MAX ->
        L5C.hpres L LBX sp WD.WD_SCR [(os, 24)] M M' -> PMSP.credit_keep cr cr' (PQM.pot_ks L PQM.SMK x g) (PQM.pot_ks L PQM.SMK x' g') ->
        model_but_vm model model' -> hi_heap HI (PM.vs_own x' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes segs SCFG (@PMSP.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSP.cfg segs fx R pc M model) K.

(* [comment removed for export] *)
End Specs.
End PQAWDC.

