Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis KL : PMK.klayout segs L.
Hypothesis SF : PMKP.sfoot A L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Variable sst : Type.
Variable str_at : (word -> option byte) -> Z -> sst -> Prop.
Variable str_own : sst -> list (Z * Z).
Variable str_size : sst -> Z.
Variable str_pot : sst -> credit.
Hypothesis STR_KEEP : forall (M M' : word -> option byte) os x, 0 <= os -> os + 24 <= 2 ^ 64 -> mem_grows M M' -> L5C.agree_on M M' os 24 -> str_at M os x -> str_at M' os x.
Variable PBPC : Z.
Hypothesis PB : WD.push_back_spec segs A L HI sst str_at str_own str_size str_pot PBPC.

(* [comment removed for export] *)
