Section Call.
Variables (M0 : word -> option byte) (model0 : Model) (K : TSet) (LBX : list (Z * Z)) (cr0 : credit).
Variables (so os sp r : Z) (x0 : sst) (SCR MAX F : Z) (cells bufs : list (Z * Z)).
Hypothesis K0 : K [].
Hypothesis Hso1 : sp <= so.
Hypothesis Hso2 : so + 8 <= hl_sptop L.
Hypothesis Hos1 : sp <= os.
Hypothesis Hos2 : os + 24 <= hl_sptop L.
Hypothesis APT : WD.apart24 so 8 os.
Hypothesis CR0 : PMSP.credit_le (str_pot x0) cr0.
Hypothesis SZ0 : str_size x0 + MAX <= WD.STR_MAX.
Hypothesis BRX : PMFR.brange L LBX.
Hypothesis HF : 0 <= F /\ F mod 16 = 0.
Hypothesis HSCR : WD.PB_SCR + F <= SCR.
Hypothesis CELLS : forall c, In c cells -> - F <= fst c /\ fst c + 8 <= 0.
Hypothesis BUFS : forall b, In b bufs -> sp - F <= fst b /\ fst b + snd b <= hl_sptop L /\ WD.apart24 (fst b) (snd b) os.

(* [comment removed for export] *)
Definition inv (n : Z) (M : word -> option byte) (model : Model) (x : sst) (cr : credit) : Prop :=
  hi_heap HI (str_own x ++ LBX) cr M (m_vmmaps model) /\ PMSP.model_ok model /\
  L5C.stk (hl_sptop L) M sp SCR /\ str_at M os x /\ str_size x = str_size x0 + n /\
  L5.u64_at segs M so os /\
  (forall c, In c cells -> L5.u64_at segs M (sp + fst c) (snd c)) /\
  (forall b, In b bufs -> L5.defined M (fst b) (snd b)) /\
  PMST.base_ok segs A M /\ PMSP.credit_keep cr0 cr (str_pot x0) (str_pot x) /\
  PMK.ek L LBX sp SCR [(os, 24)] M0 M /\ PMK.dk L LBX sp SCR M0 M /\ model_but_vm model0 model.

Lemma CALL (n c ra1 : Z) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (x : sst) (cr : credit) :
  inv n M model x cr -> 0 <= n < MAX ->
  getr R (reg 1) = Z_to_bv 64 ra1 -> L5.ra_ok ra1 -> getr R (reg 2) = Z_to_bv 64 (sp - F) ->
  getr R (reg 3) = Z_to_bv 64 (pa_gp A) -> getr R (reg 4) = Z_to_bv 64 (pa_tp A) ->
  getr R (reg 10) = Z_to_bv 64 os -> getr R (reg 11) = Z_to_bv 64 c -> 0 <= c < 256 ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : sst) (cr' : credit),
      regs_preserved R R' -> inv (n + 1) M' model' x' cr' -> srealizes segs SCFG (@PMSP.cfg segs fx' R' ra1 M' model') K) ->
  srealizes segs SCFG (@PMSP.cfg segs fx R PBPC M model) K.
