(* [comment removed for export] *)
Lemma CALLK (n c ra1 : Z) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (x : sst) (cr : credit) :
  inv n M model x cr -> 0 <= n < MAX ->
  getr R (reg 1) = Z_to_bv 64 ra1 -> L5.ra_ok ra1 -> getr R (reg 2) = Z_to_bv 64 (sp - F) ->
  getr R (reg 3) = Z_to_bv 64 (pa_gp A) -> getr R (reg 4) = Z_to_bv 64 (pa_tp A) ->
  getr R (reg 10) = Z_to_bv 64 os -> getr R (reg 11) = Z_to_bv 64 c -> 0 <= c < 256 ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : sst) (cr' : credit),
      regs_preserved R R' -> inv (n + 1) M' model' x' cr' -> L5C.agree_on M M' (sp - F) F -> srealizes segs SCFG (@PMSP.cfg segs fx' R' ra1 M' model') K) ->
  srealizes segs SCFG (@PMSP.cfg segs fx R PBPC M model) K.
Proof.
