(* [comment removed for export] *)
Section PCall.
Variables (QPC QSCR QMX : Z).
Variable qpre : bvmap 5 word -> (word -> option byte) -> Z -> Z -> Z -> Prop.
Variable qpost : bvmap 5 word -> Prop.
Hypothesis Q : VD.pusher segs A L HI sst str_at str_own str_size str_pot QPC QSCR QMX qpre qpost.
Hypothesis QSCR0 : 0 <= QSCR.
Hypothesis QMX0 : 0 <= QMX.

Lemma TAILP (n : Z) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (x : sst) (cr : credit) :
  inv n M model x cr -> 0 <= n -> n + QMX <= MAX -> QSCR <= SCR ->
  getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp ->
  getr R (reg 3) = Z_to_bv 64 (pa_gp A) -> getr R (reg 4) = Z_to_bv 64 (pa_tp A) ->
  qpre R M so os sp ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : sst) (cr' : credit),
      regs_preserved R R' -> qpost R' -> str_at M' os x' -> str_size x0 <= str_size x' <= str_size x0 + MAX ->
      L5C.hpres L LBX sp SCR [(os, 24)] M0 M' -> PMSP.credit_keep cr0 cr' (str_pot x0) (str_pot x') ->
      model_but_vm model0 model' -> hi_heap HI (str_own x' ++ LBX) cr' M' (m_vmmaps model') ->
      srealizes segs SCFG (@PMSP.cfg segs fx' R' r M' model') K) ->
  srealizes segs SCFG (@PMSP.cfg segs fx R QPC M model) K.
