(* [comment removed for export] *)
Lemma XCALL (n : Z) (M M' : word -> option byte) (model : Model) (x : sst) (cr : credit) (QSCR : Z) (W : list L5.range) :
  inv n M model x cr ->
  (forall LB a, in_errno L a -> PMK.cwr L LB a) ->
  WDL.mframe L (sp - F) QSCR W M M' -> 0 <= QSCR -> QSCR + F <= SCR ->
  (forall w, In w W -> sp - F <= fst w /\ fst w + snd w <= sp) ->
  (forall w c, In w W -> In c cells -> fst w + snd w <= sp + fst c \/ sp + fst c + 8 <= fst w) ->
  PMST.base_ok segs A M' ->
