Lemma CALLP (n ra1 : Z) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (x : sst) (cr : credit) :
  inv n M model x cr -> 0 <= n -> n + QMX <= MAX -> QSCR + F <= SCR ->
  getr R (reg 1) = Z_to_bv 64 ra1 -> L5.ra_ok ra1 -> getr R (reg 2) = Z_to_bv 64 (sp - F) ->
  getr R (reg 3) = Z_to_bv 64 (pa_gp A) -> getr R (reg 4) = Z_to_bv 64 (pa_tp A) ->
  qpre R M so os (sp - F) ->
  (forall (n' : Z) (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : sst) (cr' : credit),
      regs_preserved R R' -> qpost R' -> n <= n' <= n + QMX -> inv n' M' model' x' cr' -> srealizes segs SCFG (@PMSP.cfg segs fx' R' ra1 M' model') K) ->
  srealizes segs SCFG (@PMSP.cfg segs fx R QPC M model) K.
Proof.
