Lemma adaptor_at_agree oa ov st :
  0 <= oa -> oa + PQM.ASIZE <= 2 ^ 64 -> ag oa PQM.ASIZE ->
  (forall B m, In (B, m) (PQM.aown st) -> 0 <= B /\ B + m <= 2 ^ 64 /\ ag B m) ->
