Inductive wsh : Type := WInl (fb : Z) (len : nat) (v0 v1 : Z) | WDyn (fb p : Z) (v0 v1 : Z).
Definition ws_len (h : wsh) : nat := match h with WInl _ len _ _ => len | WDyn _ _ _ _ => 2%nat end.
Definition ws_own (h : wsh) : list (Z * Z) := match h with WInl _ _ _ _ => [] | WDyn _ p _ _ => [(p, 64)] end.
Definition ws_dyn (h : wsh) : bool := match h with WInl _ _ _ _ => false | WDyn _ _ _ _ => true end.
Definition ws_this_at (M : word -> option byte) (o : Z) (h : wsh) : Prop :=
  match h with
  | WInl fb len v0 v1 => PQTSS.binl_at M o fb len v0 v1 /\ len = PQTSS.wlen v0 v1 /\ (fb = 0 \/ fb = 2) /\ (len = 2%nat -> 1 <= v1 <= 2 ^ 30)
  | WDyn fb p v0 v1 => L5.big_at RSEGS M o (L5.BO fb 2 (L5.BDyn 8 p)) /\ (fb = 1 \/ fb = 3) /\ p mod 16 = 0
                       /\ L5.u64_at RSEGS M p v0 /\ L5.u64_at RSEGS M (p + 8) v1 /\ 0 <= v0 < 2 ^ 64 /\ 1 <= v1 <= 2 ^ 30 /\ L5.defined M p 64
  end.
