Definition addns_run_stmt : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (o y sp r : Z) (len : nat) (v0 : Z),
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 y -> 0 <= y < 2 ^ 64 ->
    getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp ->
    sp mod 16 = 0 -> 0x7fff7f800000 + PQTSS.ARITH_SCR <= sp -> L5.writable RSEGS M (sp - PQTSS.ARITH_SCR) PQTSS.ARITH_SCR -> L5.img_clear M 65536 814272 ->
    PQTSS.binl_at M o 0 len v0 0 -> (len <= 1)%nat -> (len = 0%nat -> v0 = 0) -> (len = 1%nat -> 1 <= v0) ->
    o mod 8 = 0 -> sp <= o -> o + 32 < 2 ^ 47 -> L5.writable RSEGS M o 32 ->
    exists fx' R' M' (w0 w1 : Z), msteps RSEGS (st fx R ADDU32 M) (st fx' R' r M')
      /\ mem_grows M M'
      /\ (forall a, 0 <= a < 2 ^ 64 -> ~ (sp - PQTSS.ARITH_SCR <= a < sp) -> ~ (o <= a < o + 32) -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a))
      /\ (forall i, In i L5K.CS -> getr R' (reg i) = getr R (reg i)) /\ getr R' (reg 10) = Z_to_bv 64 o
      /\ w0 + 2 ^ 64 * w1 = v0 + lo32 y /\ PQTSS.binl_at M' o 0 (PQTSS.wlen w0 w1) w0 w1.

(* [comment removed for export] *)
Definition subns_run_stmt : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (o t sp r : Z) (lt : nat) (v0 nv : Z),
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 t ->
    getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp ->
    sp mod 16 = 0 -> 0x7fff7f800000 + SUB_SCR <= sp -> L5.writable RSEGS M (sp - SUB_SCR) SUB_SCR -> L5.defined M (sp - SUB_SCR) SUB_SCR ->
    L5.img_clear M 65536 814272 ->
    PQTSS.binl_at M o 2 1 v0 0 -> 1 <= v0 ->
    PQTSS.binl_at M t 0 lt nv 0 -> (lt <= 1)%nat -> 0 <= nv < 2 ^ 32 ->
    o mod 8 = 0 -> sp <= o -> o + 32 < 2 ^ 47 -> L5.writable RSEGS M o 32 ->
    t mod 8 = 0 -> sp <= t -> t + 32 < 2 ^ 47 -> (o + 32 <= t \/ t + 32 <= o) ->
    exists fx' R' M' (w0 w1 : Z), msteps RSEGS (st fx R SUBB M) (st fx' R' r M')
      /\ mem_grows M M'
      /\ (forall a, 0 <= a < 2 ^ 64 -> ~ (sp - SUB_SCR <= a < sp) -> ~ (o <= a < o + 32) -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a))
      /\ (forall i, In i L5K.CS -> getr R' (reg i) = getr R (reg i)) /\ getr R' (reg 10) = Z_to_bv 64 o
      /\ w0 + 2 ^ 64 * w1 = v0 + (match lt with 1%nat => nv | _ => 0 end) /\ PQTSS.binl_at M' o 2 (PQTSS.wlen w0 w1) w0 w1.

