Definition grow_post (LB : list (Z * Z)) (M M' : word -> option byte) (sp o fb p w0 w1 : Z) : Prop :=
  L5.big_at RSEGS M' o (L5.BO fb 2 (L5.BDyn 8 p)) /\ p mod 16 = 0 /\ L5.u64_at RSEGS M' p w0 /\ L5.u64_at RSEGS M' (p + 8) w1
  /\ 0 <= w0 < 2 ^ 64 /\ 1 <= w1 <= 2 ^ 62 + 1
  /\ L5C.fresh_block L LB M' p 64 /\ L5C.hpres L LB sp GROW_SCR [(o, 32)] M M'.

Definition addns2_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
