(* [comment removed for export] *)
Definition tcredit (x : PM.vstr) (len : nat) (cr : credit) : credit :=
  match x with
  | PM.VShort _ => match len with 0%nat => cr | _ => debit L cr (tcap len) end
  | PM.VLong c _ _ => if ((2 <=? Z.of_nat len) && (c <=? 44))%bool then debit L cr 48 else cr
  end.
Definition tcredit_pre (x : PM.vstr) (len : nat) (cr : credit) : Prop :=
  match x with
  | PM.VShort _ => (1 <= len)%nat -> credit_ok L cr (tcap len)
  | PM.VLong c _ _ => (2 <= len)%nat -> c <= 44 -> credit_ok L cr 48
  end.
Definition ws_post (LB : list (Z * Z)) (M' : word -> option byte) (len : nat) (x x' : PM.vstr) : Prop :=
  match x, x' with
  | PM.VShort _, PM.VShort _ => len = 0%nat
  | PM.VShort _, PM.VLong c' _ p' => (1 <= len)%nat /\ c' = tcap len /\ L5C.fresh_block L LB M' p' c'
  | PM.VLong c _ p, PM.VLong c' _ p' => if ((2 <=? Z.of_nat len) && (c <=? 44))%bool then c' = 48 /\ L5C.fresh_block L LB M' p' 48 else c' = c /\ p' = p
  | PM.VLong _ _ _, PM.VShort _ => False
  end.
Definition ws_spec_sh (ok : wsh -> Prop) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (cr : credit) (o ot sp r : Z) (h : wsh) (x : PM.vstr),
    ok h ->
    hi_heap HI (PM.vs_own x ++ ws_own h ++ LB) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] ->
    getr R 10%bv = Z_to_bv 64 o -> getr R 11%bv = Z_to_bv 64 ot ->
    getr R 1%bv = Z_to_bv 64 r -> L5.ra_ok r -> getr R 2%bv = Z_to_bv 64 sp -> getr R 4%bv = Z_to_bv 64 (pa_tp AD) ->
    L5C.stk (hl_sptop L) M sp PQTSS.WRS_SCR -> PMST.base_ok RSEGS AD M ->
    ws_this_at M o h -> o mod 8 = 0 -> sp <= o -> o + 32 <= hl_sptop L ->
    PM.vstr_at RSEGS PMSP.T3 M ot x -> PM.vs_size x = 0 -> match x with PM.VShort _ => True | PM.VLong c _ _ => 26 <= c end ->
    ot mod 8 = 0 -> sp <= ot -> ot + 24 <= hl_sptop L -> (o + 32 <= ot \/ ot + 24 <= o) ->
    tcredit_pre x (ws_len h) cr ->
    (ws_dyn h = true -> 3 <= fst (tcredit x 2%nat cr) /\ 3 * 2 ^ 20 <= snd (tcredit x 2%nat cr)) ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : PM.vstr),
        regs_preserved R R' ->
        PM.vstr_at RSEGS PMSP.T3 M' ot x' -> 1 <= PM.vs_size x' <= 31 -> PQTSS.ts_text M' ot x' -> ws_post (ws_own h ++ LB) M' (ws_len h) x x' ->   (* [comment removed for export] *)
        L5C.hpres L (ws_own h ++ LB) sp PQTSS.WRS_SCR [(ot, 24)] M M' ->
        model_but_vm model model' -> hi_heap HI (PM.vs_own x' ++ ws_own h ++ LB) (tcredit x (ws_len h) cr) M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
    srealizes RSEGS SCFG (PMSP.cfg RSEGS R PQTSS.WRS M model) K.
(* [comment removed for export] *)
Definition sh_inl1 (h : wsh) : Prop := match h with WInl _ len _ v1 => (len <= 1)%nat /\ v1 = 0 | _ => False end.
Definition sh_inl2 (h : wsh) : Prop := match h with WInl _ len _ _ => len = 2%nat | _ => False end.
Definition sh_dyn (h : wsh) : Prop := match h with WDyn _ _ _ _ => True | _ => False end.
Definition ws2i_spec : Prop := ws_spec_sh sh_inl2.
Definition ws2d_spec : Prop := ws_spec_sh sh_dyn.
Definition ws_spec : Prop := ws_spec_sh (fun _ => True).

Lemma ws_spec_join : ws_spec_sh sh_inl1 -> ws2i_spec -> ws2d_spec -> ws_spec.
Proof.
  intros W1 W2 W3 fx R M model K LB cr o ot sp r h x _.
  destruct h as [fb len v0 v1|fb p v0 v1].
  - destruct (Nat.le_gt_cases len 1) as [Hl|Hl].
    + intros HH MOK HK X10 X11 X1 RA X2 X4 STK BA TH. apply (W1 fx R M model K LB cr o ot sp r (WInl fb len v0 v1) x); try assumption.
      cbn. split; [exact Hl|]. destruct TH as ((_ & _ & B1) & Hw & _). unfold PQTSS.wlen in Hw.
      destruct (Z.eqb_spec v1 0); [assumption|]. subst len. lia.
    + intros HH MOK HK X10 X11 X1 RA X2 X4 STK BA TH. apply (W2 fx R M model K LB cr o ot sp r (WInl fb len v0 v1) x); try assumption.
      cbn. destruct TH as (BI & Hw & _). unfold PQTSS.wlen in Hw. destruct (Z.eqb v1 0); [destruct (Z.eqb v0 0); subst len; lia| exact Hw].
  - intros HH. apply (W3 fx R M model K LB cr o ot sp r (WDyn fb p v0 v1) x). exact I. exact HH.
Qed.

(* [comment removed for export] *)
Lemma ws_inl1_of_ws1 : PQTSS.ws1_spec L HI -> ws_spec_sh sh_inl1.
Proof.
  intros W1 fx R M model K LB cr o ot sp r h x OK HH MOK HK X10 X11 X1 RA X2 X4 STK BA TH O8 SO OT TB SZ TBM OT8 SOT OTT DISJ CRP CRD KONT.
  destruct h as [fb len v0 v1|]; [|destruct OK]. destruct OK as (Hl & ->). cbn [ws_own ws_len app] in *.
  destruct TH as (BIN & Hw & Hfb & _).
  apply (W1 fx R M model K LB cr o ot sp r fb len v0 x HH MOK HK X10 X11 X1 RA X2 X4 STK BA BIN Hw O8 SO OT TB SZ OT8 SOT OTT DISJ).
  { destruct x as [n|c n p]; [| exact I]. intros H1. cbn [tcredit_pre] in CRP. specialize (CRP H1).
    destruct len as [|[|len']]; [exfalso; lia| exact CRP| exfalso; lia]. }
  intros fx' R' M' model' x' cr' RP TB' SZ' TT WP HP MB HH'.
  assert (E : cr' = tcredit x len cr /\ ws_post LB M' len x x').
  { unfold PQTSS.ws1_post in WP. unfold tcredit, ws_post. destruct x as [n|c n p], x' as [n'|c' n2 p'].
    - destruct WP as (-> & ->). split; reflexivity.
    - destruct WP as (H1 & -> & -> & FB). destruct len as [|[|len']]; [exfalso; lia| | exfalso; lia]. cbn. split; [reflexivity|]. split; [lia|]. split; [reflexivity| exact FB].
    - destruct WP.
    - destruct WP as (-> & -> & ->). destruct len as [|[|len']]; [| | exfalso; lia]; cbn; (split; [reflexivity| split; reflexivity]). }
  destruct E as (E1 & WP'). rewrite E1 in HH'. apply (KONT fx' R' M' model' x'); [exact RP| exact TB'| lia| exact TT| exact WP'| exact HP| exact MB| exact HH'].
Qed.
